{
  "name": "rf_build_cal_block_type3",
  "confidence": "medium",
  "docstring": "Constructs a fixed 9-byte RF calibration block of type 3 from caller fields, masks the supplied 16-bit value according to a global calibration-table flag, and conditionally fills a trailing 16-bit field from a source structure.",
  "subsystem": "rf",
  "var_renames": {
    "a1": "cal_block",
    "a2": "cal_source",
    "a3": "cal_value_u16",
    "a4": "cal_byte_field",
    "a5": "cal_word_field",
    "v5": "rf_cal_global"
  },
  "struct_hints": [
    {
      "offset": 0,
      "meaning": "destination calibration block type byte (always 3)"
    },
    {
      "offset": 1,
      "meaning": "destination calibration block subtype/version byte (always 1)"
    },
    {
      "offset": 2,
      "meaning": "destination calibration block caller-supplied byte field"
    },
    {
      "offset": 3,
      "meaning": "destination calibration block caller-supplied 16-bit field/selector"
    },
    {
      "offset": 5,
      "meaning": "destination calibration block 16-bit value; LSB forced clear when rf_cal_global[371] is zero"
    },
    {
      "offset": 7,
      "meaning": "destination calibration block 16-bit auxiliary field; zeroed when offset-3 field is nonzero, otherwise copied from source offset 14"
    },
    {
      "offset": 371,
      "meaning": "rf_cal_global flag byte controlling the LSB mask of cal_value_u16"
    }
  ]
}
